// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract Staking is Initializable{

    event FundsWithdrawn(address owner,uint amount,uint date);
    event Staked(address owner,uint amount,uint date);
    event Unstaked(address owner,uint date);
    event StakingEnded(uint leftoverBalance, uint date);
    

    struct stakeholder{
        address _address;
        uint joinedOn;
        uint lastWithdrawedOn;
    }

    stakeholder[] internal stakeholders;
    IBEP20 public asset;
    address admin;
    uint totalBalance;


    mapping(address=>uint) public stakes;
    mapping(address=>uint) public rewards;

    // constructor(address _admin,address _asset,uint _total){
    //     asset = IBEP20(_asset);
    //     admin = _admin;
    //     totalBalance = _total;
    // }

    function initialize(address _admin,address _asset,uint _total)public initializer{
        asset = IBEP20(_asset);
        admin = _admin;
        totalBalance = _total;
    }



    function createStake(uint _stake) public payable {
            stakes[msg.sender] += _stake;
            asset.transferFrom(msg.sender, payable(address(this)),_stake);
            emit Staked(msg.sender,_stake,block.timestamp);
    }

    function removeStake(address _stakeholder) public {
        uint s = stakes[_stakeholder];
        if(stakes[_stakeholder] == 0) return;
        stakes[_stakeholder] = 0;
        asset.transferFrom(address(this),payable(_stakeholder),s);
        emit Unstaked(msg.sender,block.timestamp);
    }

    function createStakeHolder(uint _stake) public{
        require(_stake > 0,"cannot stake an invalid amount");
        stakeholder memory s = stakeholder(payable(msg.sender),block.timestamp,block.timestamp);
        stakeholders.push(s);
        createStake(_stake);
    }

    
    receive() external payable{}

    function stakeOf (address _stakeholder)public view returns (uint){
        return stakes[_stakeholder];
    }

    function totalStake() public view returns (uint){
        uint total = 0;
        for(uint i = 0; i < stakeholders.length; i += 1){
            total += stakes[stakeholders[i]._address];
        }
        return total;
    }
 

    function isStakeholder(address _stakeholder) public view returns (bool,uint){
        for(uint i = 0; i < stakeholders.length; i +=1){
            if(stakeholders[i]._address == _stakeholder){
                return (true,i);
            }
        }
        return (false,0);
    }

    function totalStakeholders () public view returns (uint){
        return stakeholders.length;
    }

    function removeStakeHolder() public {
        (bool _isStakeholder,uint index) = isStakeholder(msg.sender);
          if(_isStakeholder){
            stakeholders[index] = stakeholders[stakeholders.length - 1];
            stakeholders.pop();
            removeStake(msg.sender);
        }
    }

    function rewardOf(address _stakeholder)view public returns (uint){
        return rewards[_stakeholder];
    }

    function calculateReward(address _stakeholder) public view returns (uint) {
        uint ONE_YEAR = 31556926;
        (bool _isStakeholder,uint index) = isStakeholder(_stakeholder);
        uint _staked = stakes[_stakeholder];
        require(_isStakeholder , "not a stake holder");
        stakeholder memory s = stakeholders[index];
        uint timeDifference = block.timestamp - s.lastWithdrawedOn;
        uint _percentage = (timeDifference * 15)/(ONE_YEAR * 100);
        return _percentage * _staked;
    }

    function withdrawReward() public {
        (bool _isStakeholder,uint index) = isStakeholder(msg.sender);
        uint r = calculateReward(msg.sender);
        uint _reward = rewards[msg.sender];
        require(_isStakeholder == true, "you must be a stake holder");
        require(stakes[stakeholders[index]._address] > 0,"you dont have any stake");
        require(r > 0, "no available reward");
        if(r > totalBalance){
            rewards[msg.sender] = 0;
            totalBalance -= _reward;
            stakeholders[index].lastWithdrawedOn = block.timestamp;
            asset.transferFrom(address(this),payable(msg.sender),_reward);
            emit FundsWithdrawn(msg.sender,r,block.timestamp);
            return;
        }else{
        rewards[msg.sender] = 0;
        totalBalance -= r;
        stakeholders[index].lastWithdrawedOn = block.timestamp;
        asset.transferFrom(address(this),payable(msg.sender),r);
        }
    }

    function distributeReward() public {
        require(msg.sender == admin, "only admin");
        for(uint i = 0; i < stakeholders.length; i += 1){
            address _stakeholder = stakeholders[i]._address;
            uint reward = calculateReward(_stakeholder);
            rewards[_stakeholder] = reward;
        }
    }

    function totalReward() public view returns (uint){
        uint _total = 0;
        for(uint i = 0; 1 < stakeholders.length; i += 1){
            _total += rewards[stakeholders[i]._address];
        }
        return _total;
    }

    function endStaking() external {
        require(msg.sender == admin,"admin only");
        uint _total = totalBalance;
        totalBalance = 0;
        asset.transferFrom(address(this),payable(msg.sender),_total);
        emit StakingEnded(_total,block.timestamp);
    }
}
